const ALL_IMAGES = IMAGES.concat(SIGN_IMAGES);

self.addEventListener('install', (e) => {
  // НЕ skipWaiting: новая версия ждёт, пока приложение полностью закроют,
  // и активируется при следующем запуске — без перезагрузки посреди сессии.
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(CORE)).catch(() => {}));
});

self.addEventListener('activate', (e) => {
  e.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k)));
    // НЕ clients.claim(): не перехватываем уже открытую вкладку, чтобы не дёргать
    // пользователя перезагрузкой. Новая версия начнёт работать со следующего запуска.
    // фоновое докачивание картинок билетов для полного офлайна (best-effort)
    const c = await caches.open(CACHE);
    for (let i = 0; i < ALL_IMAGES.length; i += 20) {
      await Promise.all(ALL_IMAGES.slice(i, i + 20).map((u) => c.add(u).catch(() => {})));
    }
  })());
});

// Стратегия: ВСЁ network-first — онлайн отдаём свежее с бэка и параллельно кладём
// в кэш; из кэша берём только когда сети нет. Исключение — неизменяемые ассеты
// (картинки, шрифты: имя файла = содержимое), они cache-first, чтобы не качать их
// по сети каждый раз и не жечь мобильный трафик.
const CACHEFIRST = /(\/assets\/(?:tickets|signs|icons)\/|\/assets\/fonts\/[^/]+\.woff2$)/;
self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== location.origin) return;
  const cacheFirst = CACHEFIRST.test(url.pathname);
  e.respondWith((async () => {
    if (cacheFirst) {
      const cached = await caches.match(req, { ignoreSearch: true });
      if (cached) return cached;
      try {
        const res = await fetch(req);
        if (res && res.ok && res.type === 'basic') { const c = await caches.open(CACHE); c.put(req, res.clone()); }
        return res;
      } catch (err) { throw err; }
    }
    try {
      const res = await fetch(req);
      if (res && res.ok && res.type === 'basic') { const c = await caches.open(CACHE); c.put(req, res.clone()); }
      return res;
    } catch (err) {
      const cached = await caches.match(req, { ignoreSearch: true });
      if (cached) return cached;
      if (req.mode === 'navigate') return (await caches.match('index.html')) || (await caches.match('./'));
      throw err;
    }
  })());
});

// Сообщения от страницы: статус кэша и докачка всего для офлайна (с прогрессом).
async function cachedCount(c, list) {
  let n = 0;
  await Promise.all(list.map(async (u) => { if (await c.match(u, { ignoreSearch: true })) n++; }));
  return n;
}
self.addEventListener('message', (e) => {
  const msg = e.data || {};
  const reply = (m) => { if (e.source) e.source.postMessage(m); };
  if (msg.type === 'cacheStatus') {
    e.waitUntil((async () => {
      const c = await caches.open(CACHE);
      const all = CORE.concat(ALL_IMAGES);
      reply({ type: 'cacheStatus', cached: await cachedCount(c, all), total: all.length });
    })());
  } else if (msg.type === 'precacheAll') {
    e.waitUntil((async () => {
      const c = await caches.open(CACHE);
      const all = CORE.concat(ALL_IMAGES);
      let done = 0;
      for (let i = 0; i < all.length; i += 12) {
        await Promise.all(all.slice(i, i + 12).map(async (u) => {
          try { if (!(await c.match(u, { ignoreSearch: true }))) await c.add(u); } catch (err) {}
          done++;
        }));
        reply({ type: 'precacheProgress', cached: done, total: all.length });
      }
      reply({ type: 'precacheDone', cached: await cachedCount(c, all), total: all.length });
    })());
  }
});
